mapper.select:
SELECT id, title, event_date, total_tickets, available_tickets, ticket_price
FROM events
WHERE id = #{id, jdbcType=OTHER, typeHandler=org.apache.ibatis.type.ObjectTypeHandler}

mapper.update:
UPDATE events
SET available_tickets = available_tickets - #{quantity}
WHERE id = #{id, jdbcType=OTHER, typeHandler=org.apache.ibatis.type.ObjectTypeHandler}
  AND available_tickets >= #{quantity}
